from gguf import GGUFReader

reader = GGUFReader("{{gguf_path}}")

def info():
    print("fields:")
    for k, v in reader.fields.items():
        print(f"  {k}: {v.parts}")
    print("tensors:", len(reader.tensors))
    for t in reader.tensors[:5]:
        print(f"  {t.name} {t.shape} {t.tensor_type}")

if __name__ == "__main__":
    info()
